package com.bank.dump;

import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class BoundRefDemo {
    private static final Logger log = Logger.getLogger("Dump");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> txns = List.of("TXN-1: 50000", "TXN-2: 25000", "TXN-3: 7000");
        DumpService service = new DumpService(log);

        // bound reference: receiver fixed as System.out
        Consumer<String> printer = System.out::println;
        txns.forEach(printer);                 // quick console dump

        service.logAll(txns);                  // production-style logging
    }
}

// ─── Would be in service/DumpService.java ───
class DumpService {
    private final Logger log;
    DumpService(Logger log) { this.log = log; }

    void logAll(List<String> lines) {
        // production: bound reference on a Logger, with a level
        lines.forEach(line -> log.info(() -> "txn: " + line));
    }
}
